"""ops.macos_research_panel_daily: hk_market_capture (review candidate, not deployment)."""
from __future__ import annotations
import base64
import hashlib
import json
import math
import re
from datetime import date, datetime, time, timezone
from decimal import Decimal
from typing import Any, Mapping
from ._namespace import read_global as _v4_global


_HK_CAPTURE_V2_SCHEMA = "v4.manager_hk_connect_capture.v2"
_HK_CAPTURE_SERIALIZATION_V2 = "futu.dataframe.records.canonical-json.v1"
_HK_FORWARD_SOURCE_SET = {
    "source_head": "55a5ba0b8aef8e83dfd04fdbabefb8d9baa1d054",
    "forward_receipt_sha256": "69ed8c29225b9476ed358f76769ac1ec37a7f4d94806a8b803138901f789523e",
    "candidate_manifest_sha256": "75f6f5543137319810b1f433cefa83ae89c204c2bf6ab56c42effa4be89a6366",
    "candidate_build_receipt_sha256": "439d5ffba4475b5183a2d74e7cc518693391b7b3b9a3fcc18f95be4b77aea194",
    "api_writer_receipt_sha256": "3ea98364f997591e1cecba92758a35dff6c4cb0bb0136a43bcb3524f1d734a4d",
    "api_reviewer_receipt_sha256": "daf18d4bf0a763187708c8f263385d09f668a77ac1d9c4948361b4a8c9855790",
    "api_source_mapping_sha256": "5c66286e130e971cf89f256e8cb001e2d951dc67ac3db27d93a0f37ff76e1feb",
}


def _canonical_capture_bytes(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")


def _sdk_json_value(value: Any) -> Any:
    """Encode SDK DataFrame values without dropping columns or row positions."""
    if value is None or isinstance(value, (str, bool, int)):
        return value
    if isinstance(value, float):
        return value if math.isfinite(value) else {"$float": repr(value)}
    if isinstance(value, Decimal):
        return {"$decimal": str(value)}
    if isinstance(value, (datetime, date, time)):
        return {"$datetime": value.isoformat()}
    if isinstance(value, bytes):
        return {"$bytes_base64": base64.b64encode(value).decode("ascii")}
    if isinstance(value, Mapping):
        if any(not isinstance(key, str) for key in value):
            raise TypeError("Futu SDK row has a non-string key")
        return {key: _sdk_json_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_sdk_json_value(item) for item in value]
    if type(value).__name__ in {"NAType", "NaTType"}:
        return {"$missing_scalar": type(value).__name__}
    item = getattr(value, "item", None)
    if callable(item):
        try:
            scalar = item()
        except (TypeError, ValueError):
            scalar = value
        if scalar is not value:
            return _sdk_json_value(scalar)
    raise TypeError(f"unsupported Futu SDK value type: {type(value).__name__}")


def _sdk_dataframe_records(frame: Any) -> tuple[list[str], list[dict[str, Any]]]:
    if frame is None or not callable(getattr(frame, "to_dict", None)):
        raise TypeError("Futu plate response is not a usable DataFrame")
    columns_value = getattr(frame, "columns", None)
    if columns_value is None:
        raise TypeError("Futu plate DataFrame columns are missing")
    columns = [str(_sdk_json_value(column)) for column in list(columns_value)]
    if len(columns) != len(set(columns)):
        raise TypeError("Futu plate DataFrame columns are duplicated")
    records = frame.to_dict(orient="records")
    if not isinstance(records, list):
        raise TypeError("Futu plate DataFrame records are malformed")
    normalized = []
    for record in records:
        if not isinstance(record, Mapping):
            raise TypeError("Futu plate DataFrame row is malformed")
        row = _sdk_json_value(record)
        if not isinstance(row, dict):
            raise TypeError("Futu plate DataFrame row is malformed")
        normalized.append(row)
    return columns, normalized


def _utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="microseconds")


def _collect_hk_futu_rows_body(_v4_scope, /, target_date, *, context_factory, batch_size, minimum_universe_count, required_coverage_ratio, membership_ready_callback=None):
    """Collect an exact-date full HK Connect snapshot from Futu OpenD."""
    target = _v4_global(_v4_scope, '_date')(target_date)
    capture_manifest_value = _v4_global(_v4_scope, 'os').environ.get("V35_HK_CAPTURE_PATH")
    capture_manifest_path = (
        _v4_global(_v4_scope, 'Path')(capture_manifest_value).expanduser()
        if capture_manifest_value
        else None
    )
    capture_raw_path = (
        capture_manifest_path.with_name(f"{capture_manifest_path.stem}.capture.json")
        if capture_manifest_path is not None
        else None
    )
    capture_run_id = (
        _v4_global(_v4_scope, 'os').environ.get("V35_HK_CAPTURE_RUN_ID")
        or capture_manifest_path.stem
        if capture_manifest_path is not None
        else None
    )

    def write_manifest(payload):
        if capture_manifest_path is None:
            return
        if capture_manifest_path.is_symlink():
            raise _v4_global(_v4_scope, 'SnapshotGateError')("HK capture manifest path must not be a symlink")
        if capture_manifest_path.exists():
            try:
                existing = _v4_global(_v4_scope, 'json').loads(
                    capture_manifest_path.read_bytes().decode("utf-8-sig")
                )
            except (OSError, UnicodeError, _v4_global(_v4_scope, 'json').JSONDecodeError) as error:
                raise _v4_global(_v4_scope, 'SnapshotGateError')(
                    f"HK capture manifest path is not a pending or ready envelope: {capture_manifest_path}"
                ) from error
            if _v4_global(_v4_scope, 'isinstance')(existing, _v4_global(_v4_scope, 'Mapping')) and existing.get("status") == "READY":
                if capture_manifest_path.read_bytes() != payload:
                    raise _v4_global(_v4_scope, 'SnapshotGateError')(
                        f"HK capture manifest is immutable and already READY: {capture_manifest_path}"
                    )
                return
        _v4_global(_v4_scope, '_atomic_write')(capture_manifest_path, payload)

    def write_raw_capture(payload):
        if capture_raw_path is None:
            return
        if capture_raw_path.is_symlink():
            raise _v4_global(_v4_scope, 'SnapshotGateError')("HK capture raw path must not be a symlink")
        if capture_raw_path.exists():
            if capture_raw_path.read_bytes() != payload:
                raise _v4_global(_v4_scope, 'SnapshotGateError')(
                    f"HK raw capture path is immutable: {capture_raw_path}"
                )
            return
        _v4_global(_v4_scope, '_atomic_write')(capture_raw_path, payload)

    if capture_manifest_path is not None:
        write_manifest(
            _v4_global(_v4_scope, 'json').dumps(
                {
                    "schema_version": "v3.macos.research_panel_hk_capture_manifest.v1",
                    "status": "PENDING",
                    "target_date": target,
                    "capture_run_id": capture_run_id,
                    "capture_relative_path": capture_raw_path.name,
                },
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        )
    plates = tuple(_v4_global(_v4_scope, 'HKCONNECT_PLATE_CODES'))
    source_path = _v4_global(_v4_scope, 'Path')(__file__).resolve()
    forward_source_set = dict(_HK_FORWARD_SOURCE_SET)
    producer_owner = {
        "workload_id": "v35_dispatcher.research_panel_daily_hk",
        "code_ref": "ops/_macos_research_panel_daily_parts/hk_market_capture.py",
        "code_sha256": hashlib.sha256(source_path.read_bytes()).hexdigest(),
        "forward_source_set": forward_source_set,
        "forward_source_set_sha256": hashlib.sha256(_canonical_capture_bytes(forward_source_set)).hexdigest(),
    }

    def _write_sdk_capture(payload):
        if capture_manifest_path is None:
            return None
        path = capture_manifest_path.with_name(f"{capture_manifest_path.stem}.sdk.capture.json")
        encoded = _canonical_capture_bytes(payload)
        if path.is_symlink():
            raise _v4_global(_v4_scope, 'SnapshotGateError')("HK SDK capture path must not be a symlink")
        if path.exists() and path.read_bytes() != encoded:
            raise _v4_global(_v4_scope, 'SnapshotGateError')("HK SDK capture path is immutable")
        if not path.exists():
            _v4_global(_v4_scope, '_atomic_write')(path, encoded)
        return path, encoded

    def _save_failed_capture(responses, errors, *, sdk_receipt=None):
        capture = {
            "schema_version": _HK_CAPTURE_V2_SCHEMA,
            "status": "FAILED",
            "membership_status": "FAILED",
            "target_date": target,
            "capture_run_id": capture_run_id,
            "capture_receipt_ref": capture_manifest_path.name if capture_manifest_path is not None else None,
            "producer_owner": producer_owner,
            "plate_responses": responses,
            "capture_errors": list(errors),
            **_v4_global(_v4_scope, 'SAFETY_FLAGS'),
        }
        if sdk_receipt is not None:
            capture["sdk_capture_ref"] = sdk_receipt[0].name
            capture["sdk_capture_sha256"] = hashlib.sha256(sdk_receipt[1]).hexdigest()
        capture["capture_sha256"] = _v4_global(_v4_scope, '_canonical_sha')(capture)
        if capture_manifest_path is not None:
            capture_bytes = _canonical_capture_bytes(capture)
            capture_raw_sha = hashlib.sha256(capture_bytes).hexdigest()
            write_raw_capture(capture_bytes)
            write_manifest(_canonical_capture_bytes({
                "schema_version": "v3.macos.research_panel_hk_capture_manifest.v1",
                "status": "FAILED",
                "target_date": target,
                "capture_run_id": capture_run_id,
                "capture_relative_path": capture_raw_path.name,
                "capture_path": capture_raw_path.name,
                "capture": capture,
                "capture_sha256": capture["capture_sha256"],
                "capture_raw_sha256": capture_raw_sha,
                "capture_errors": list(errors),
            }))
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK Futu membership capture incomplete: " + ",".join(errors)
        )

    if context_factory is None:
        def context_factory():
            import futu

            return futu.OpenQuoteContext(host="127.0.0.1", port=11111)
    context = None
    context_error = None
    try:
        context = context_factory()
    except Exception as error:
        context_error = type(error).__name__
    plate_responses: dict[str, dict[str, Any]] = {}
    capture_errors: list[str] = []
    if context is None:
        capture_errors.append("CONTEXT_INIT:" + (context_error or "FAILED"))
        for plate_code in plates:
            response_material = {
                "requested_plate": plate_code,
                "serialization_version": _HK_CAPTURE_SERIALIZATION_V2,
                "columns": [], "rows": [],
            }
            plate_responses[plate_code] = {
                **response_material,
                "row_count": 0,
                "return_code": None,
                "requested_at": _utc_now_iso(),
                "completed_at": _utc_now_iso(),
                "error_kind": "CONTEXT_INIT_FAILED",
                "response_sha256": _v4_global(_v4_scope, '_canonical_sha')(response_material),
            }
        sdk_receipt = _write_sdk_capture({
            "schema_version": _HK_CAPTURE_V2_SCHEMA,
            "target_date": target,
            "capture_run_id": capture_run_id,
            "producer_owner": producer_owner,
            "plate_responses": plate_responses,
            "status": "FAILED",
        })
        _save_failed_capture(plate_responses, capture_errors, sdk_receipt=sdk_receipt)

    universe: dict[str, str] = {}
    per_plate_codes: dict[str, list[str]] = {}
    snapshots: dict[str, dict[str, Any]] = {}
    codes: list[str] = []
    close_error = None
    snapshot_failure = None
    try:
        for plate_code in plates:
            requested_at = _utc_now_iso()
            return_code = None
            frame = None
            error_kind = None
            try:
                returned = context.get_plate_stock(plate_code)
                if not isinstance(returned, (tuple, list)) or len(returned) != 2:
                    raise TypeError("Futu plate return is not (RET, DataFrame)")
                return_code, frame = returned
            except Exception as error:
                error_kind = type(error).__name__
            completed_at = _utc_now_iso()
            try:
                columns, frame_rows = _sdk_dataframe_records(frame)
            except Exception as error:
                columns, frame_rows = [], []
                error_kind = error_kind or type(error).__name__
            return_code_type = type(return_code).__name__
            return_code_ok = type(return_code) is int and return_code == 0
            try:
                # Keep JSON-native SDK values unchanged for audit.  A value
                # that cannot be serialized is represented with its type and
                # repr, and is never treated as RET_OK.
                captured_return_code = json.loads(json.dumps(
                    return_code, ensure_ascii=False, allow_nan=False
                ))
            except (TypeError, ValueError, OverflowError):
                captured_return_code = {
                    "unserializable_type": f"{type(return_code).__module__}.{type(return_code).__qualname__}",
                    "repr": repr(return_code)[:256],
                }
            response_material = {
                "requested_plate": plate_code,
                "serialization_version": _HK_CAPTURE_SERIALIZATION_V2,
                "columns": columns,
                "rows": frame_rows,
            }
            response = {
                **response_material,
                "return_code": captured_return_code,
                "return_code_type": return_code_type,
                "return_code_ok": return_code_ok,
                "requested_at": requested_at,
                "completed_at": completed_at,
                "row_count": len(frame_rows),
                "response_sha256": _v4_global(_v4_scope, '_canonical_sha')(response_material),
            }
            if error_kind:
                response["error_kind"] = error_kind
            plate_responses[plate_code] = response
            if not return_code_ok:
                capture_errors.append(f"RET_NOT_OK:{plate_code}")
            if error_kind:
                capture_errors.append(f"FRAME_INVALID:{plate_code}")
            if not frame_rows:
                capture_errors.append(f"FRAME_EMPTY:{plate_code}")

        # Persist the complete structured SDK frames before deriving the
        # membership sets or requesting quote snapshots.  This is SDK output,
        # not a claim about the provider's wire bytes or upstream completeness.
        sdk_payload = {
            "schema_version": _HK_CAPTURE_V2_SCHEMA,
            "target_date": target,
            "capture_run_id": capture_run_id,
            "producer_owner": producer_owner,
            "plate_responses": plate_responses,
            "status": "RAW_CAPTURED" if not capture_errors else "FAILED",
            **_v4_global(_v4_scope, 'SAFETY_FLAGS'),
        }
        sdk_receipt = _write_sdk_capture(sdk_payload)

        # Membership derives only from the two retained plate frames.  Quote
        # rows and same-day quote coverage never alter this set.
        for plate_code in plates:
            response = plate_responses.get(plate_code)
            if not isinstance(response, Mapping):
                capture_errors.append(f"PLATE_MISSING:{plate_code}")
                continue
            frame_rows = response.get("rows")
            if not isinstance(frame_rows, list):
                capture_errors.append(f"FRAME_INVALID:{plate_code}")
                continue
            plate_codes: set[str] = set()
            for item in frame_rows:
                code = item.get("code")
                if not isinstance(code, str) or not re.fullmatch(r"HK\.\d{5}", code):
                    capture_errors.append(f"CODE_INVALID:{plate_code}")
                    continue
                plate_codes.add(code)
                universe.setdefault(code, _v4_global(_v4_scope, 'str')(item.get("stock_name") or item.get("name") or "").strip())
            per_plate_codes[plate_code] = sorted(plate_codes)

        if not capture_errors:
            if len(per_plate_codes) != len(plates) or any(not per_plate_codes.get(plate) for plate in plates):
                capture_errors.append("PLATE_SET_INCOMPLETE")
            else:
                codes = _v4_global(_v4_scope, 'sorted')(universe)
                minimum_universe = _v4_global(_v4_scope, 'max')(
                    600, _v4_global(_v4_scope, 'int')(minimum_universe_count)
                )
                if _v4_global(_v4_scope, 'len')(codes) < minimum_universe:
                    raise _v4_global(_v4_scope, 'SnapshotGateError')(
                        f"HK universe below minimum: {_v4_global(_v4_scope, 'len')(codes)} < {minimum_universe_count}"
                    )
                step = _v4_global(_v4_scope, 'max')(1, _v4_global(_v4_scope, 'int')(batch_size))
                for offset in _v4_global(_v4_scope, 'range')(0, _v4_global(_v4_scope, 'len')(codes), step):
                    try:
                        return_code, frame = context.get_market_snapshot(codes[offset : offset + step])
                        if return_code != 0:
                            raise _v4_global(_v4_scope, 'SnapshotGateError')(
                                f"Futu market snapshot failed at offset {offset}"
                            )
                        batch_codes: set[str] = _v4_global(_v4_scope, 'set')()
                        for item in _v4_global(_v4_scope, '_frame_records')(frame):
                            code = _v4_global(_v4_scope, 'str')(item.get("code") or "").strip().upper()
                            if not code or code not in universe:
                                raise _v4_global(_v4_scope, 'SnapshotGateError')(
                                    f"Futu market snapshot returned unmatched code: {code!r}"
                                )
                            if code in batch_codes:
                                raise _v4_global(_v4_scope, 'SnapshotGateError')(
                                    f"Futu market snapshot returned duplicate code: {code}"
                                )
                            batch_codes.add(code)
                            snapshots[code] = item
                    except Exception as error:
                        snapshot_failure = error
                        break
    finally:
        close = _v4_global(_v4_scope, 'getattr')(context, "close", None)
        if _v4_global(_v4_scope, 'callable')(close):
            try:
                close()
            except Exception as error:
                close_error = type(error).__name__
    if close_error:
        snapshot_failure = snapshot_failure or _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK Futu context close failed: " + close_error
        )
    if capture_errors:
        _save_failed_capture(plate_responses, capture_errors, sdk_receipt=sdk_receipt)
    if len(per_plate_codes) != len(plates) or any(not per_plate_codes.get(plate) for plate in plates):
        _save_failed_capture(plate_responses, ["PLATE_SET_INCOMPLETE"], sdk_receipt=sdk_receipt)
    rows: list[dict[str, Any]] = []
    excluded: dict[str, list[str]] = {}
    positive_volume_count = 0
    positive_turnover_count = 0
    required_fields = ("open_price", "high_price", "low_price", "last_price", "volume", "turnover")
    for code in codes:
        source = snapshots.get(code) or {}
        if _v4_global(_v4_scope, '_compact_datetime')(source.get("update_time")) != target:
            excluded[code] = ["stale_or_missing_date"]
            continue
        missing = [field for field in required_fields if field not in source or source.get(field) in (None, "")]
        if missing:
            excluded[code] = [f"missing_{field}" for field in missing]
            continue
        try:
            open_price = _v4_global(_v4_scope, '_number')(source, "open_price")
            high_price = _v4_global(_v4_scope, '_number')(source, "high_price")
            low_price = _v4_global(_v4_scope, '_number')(source, "low_price")
            last_price = _v4_global(_v4_scope, '_number')(source, "last_price")
            volume = _v4_global(_v4_scope, '_number')(source, "volume")
            turnover = _v4_global(_v4_scope, '_number')(source, "turnover")
        except (_v4_global(_v4_scope, 'TypeError'), _v4_global(_v4_scope, 'ValueError'), _v4_global(_v4_scope, 'SnapshotGateError')):
            excluded[code] = ["non_numeric_fields"]
            continue
        reasons: list[str] = []
        if volume > 0:
            positive_volume_count += 1
        else:
            reasons.append("non_positive_volume")
        if turnover > 0:
            positive_turnover_count += 1
        else:
            reasons.append("non_positive_turnover")
        if _v4_global(_v4_scope, 'min')(open_price, high_price, low_price, last_price) <= 0 or high_price < low_price or last_price < low_price or last_price > high_price:
            reasons.append("non_positive_ohlc")
        if reasons:
            excluded[code] = reasons
            continue
        try:
            row = {
                "trade_date": target,
                "code": code,
                "name": _v4_global(_v4_scope, 'str')(source.get("name") or universe.get(code) or "").strip(),
                "open": open_price,
                "high": high_price,
                "low": low_price,
                "close": last_price,
                "volume": _v4_global(_v4_scope, 'int')(_v4_global(_v4_scope, 'round')(volume)),
                "turnover": turnover,
                "source": "FUTU_HKCONNECT_SNAPSHOT",
            }
            rows.append(row)
        except (_v4_global(_v4_scope, 'TypeError'), _v4_global(_v4_scope, 'ValueError'), _v4_global(_v4_scope, 'SnapshotGateError')):
            excluded[code] = ["row_encoding_error"]
            continue
    coverage = _v4_global(_v4_scope, 'len')(rows) / _v4_global(_v4_scope, 'max')(_v4_global(_v4_scope, 'len')(codes), 1)
    positive_volume_coverage = positive_volume_count / _v4_global(_v4_scope, 'max')(_v4_global(_v4_scope, 'len')(codes), 1)
    positive_turnover_coverage = positive_turnover_count / _v4_global(_v4_scope, 'max')(_v4_global(_v4_scope, 'len')(codes), 1)
    minimum_universe = _v4_global(_v4_scope, 'max')(600, _v4_global(_v4_scope, 'int')(minimum_universe_count))
    quote_errors = []
    if snapshot_failure is not None:
        safe_detail = (
            str(snapshot_failure)
            if isinstance(snapshot_failure, _v4_global(_v4_scope, 'SnapshotGateError'))
            else "SDK_EXCEPTION"
        )
        quote_errors.append(type(snapshot_failure).__name__ + ":" + safe_detail)
    if _v4_global(_v4_scope, 'len')(rows) < minimum_universe:
        quote_errors.append(
            "HK exact-date coverage below gate: "
            f"universe={_v4_global(_v4_scope, 'len')(codes)},rows={_v4_global(_v4_scope, 'len')(rows)},coverage={coverage:.8f}"
        )
    if positive_volume_coverage + 1e-12 < 0.8 or positive_turnover_coverage + 1e-12 < 0.8:
        quote_errors.append(
            "HK positive-trade coverage below gate: "
            f"volume={positive_volume_coverage:.8f},turnover={positive_turnover_coverage:.8f}"
        )
    if coverage + 1e-12 < _v4_global(_v4_scope, 'float')(required_coverage_ratio):
        quote_errors.append(f"HK exact-date coverage below gate: universe={_v4_global(_v4_scope, 'len')(codes)},rows={_v4_global(_v4_scope, 'len')(rows)},coverage={coverage:.8f}")
    evidence_codes = _v4_global(_v4_scope, 'sorted')(excluded)
    evidence_codes_limited = evidence_codes[:_v4_global(_v4_scope, 'MAX_EXCLUDED_EVIDENCE')]
    evidence_reasons = {code: _v4_global(_v4_scope, 'sorted')(excluded[code]) for code in evidence_codes_limited}
    source_payload = {
        "target_date": target,
        "plates": _v4_global(_v4_scope, 'HKCONNECT_PLATE_CODES'),
        "rows": rows,
        "excluded_count": _v4_global(_v4_scope, 'len')(evidence_codes),
        "excluded_codes": evidence_codes,
        "excluded_reasons": {code: _v4_global(_v4_scope, 'sorted')(excluded[code]) for code in evidence_codes},
        "positive_volume_coverage_rate": positive_volume_coverage,
        "positive_turnover_coverage_rate": positive_turnover_coverage,
    }
    source_sha = _v4_global(_v4_scope, '_canonical_sha')(source_payload)
    security_fields = (
        "code", "name", "outstanding_shares", "circular_market_val", "listing_date",
        "lot_size", "stock_owner", "stock_child_type", "sec_status",
    )
    security_master_rows = [
        {
            field: (
                code
                if field == "code"
                else source.get(field)
                if field != "name"
                else _v4_global(_v4_scope, 'str')(
                    source.get("name") or universe.get(code) or ""
                ).strip()
            )
            for field in security_fields
        }
        for code in codes
        for source in (snapshots.get(code) or {},)
    ]
    plate_sets = [set(per_plate_codes[plate]) for plate in plates]
    acquired_at = max(
        datetime.fromisoformat(plate_responses[plate]["completed_at"].replace("Z", "+00:00"))
        for plate in plates
    ).isoformat()
    plate_response_counts = {plate: plate_responses[plate]["row_count"] for plate in plates}
    plate_response_sha256 = {plate: plate_responses[plate]["response_sha256"] for plate in plates}
    membership_source_payload = {
        "target_date": target,
        "plate_codes": {plate: per_plate_codes[plate] for plate in plates},
        "plate_response_sha256": plate_response_sha256,
        "capture_run_id": capture_run_id,
        "acquired_at": acquired_at,
    }
    sdk_capture_ref = sdk_receipt[0].name if sdk_receipt is not None else None
    sdk_capture_sha256 = hashlib.sha256(sdk_receipt[1]).hexdigest() if sdk_receipt is not None else None
    capture = {
        "schema_version": _HK_CAPTURE_V2_SCHEMA,
        "status": "READY",
        "membership_status": "READY",
        "target_date": target,
        "capture_run_id": capture_run_id,
        "capture_receipt_ref": capture_manifest_path.name if capture_manifest_path is not None else None,
        "producer_owner": producer_owner,
        "plate_responses": plate_responses,
        "plate_codes": {plate: per_plate_codes[plate] for plate in plates},
        "plate_response_counts": plate_response_counts,
        "plate_response_sha256": plate_response_sha256,
        "acquired_at": acquired_at,
        "membership_source_payload": membership_source_payload,
        "membership_source_sha256": _v4_global(_v4_scope, '_canonical_sha')(membership_source_payload),
        "overlap_count": len(plate_sets[0] & plate_sets[1]),
        "code_count": len(codes),
        "plates": list(plates),
        "codes": list(codes),
        "sdk_capture_ref": sdk_capture_ref,
        "sdk_capture_sha256": sdk_capture_sha256,
        "rows": rows,
        "security_master_rows": security_master_rows,
        "source_payload": source_payload,
        "source_sha256": source_sha,
        "quote_status": "FAILED" if quote_errors else "READY",
        "quote_errors": quote_errors,
        "panel_status": "BLOCKED_BY_QUOTE_GATE" if quote_errors else "PENDING_PANEL_GATE",
        **_v4_global(_v4_scope, 'SAFETY_FLAGS'),
    }
    capture["capture_sha256"] = _v4_global(_v4_scope, '_canonical_sha')(capture)
    if capture_manifest_path is not None:
        capture_bytes = _canonical_capture_bytes(capture)
        capture_raw_sha256 = _v4_global(_v4_scope, 'hashlib').sha256(capture_bytes).hexdigest()
        write_raw_capture(capture_bytes)
        stale_codes = sorted(
            code for code in evidence_codes
            if "stale_or_missing_date" in set(excluded.get(code, ()))
        )
        write_manifest(
            _v4_global(_v4_scope, 'json').dumps(
                {
                    "schema_version": "v3.macos.research_panel_hk_capture_manifest.v1",
                    "status": "PENDING" if quote_errors else "READY",
                    "target_date": target,
                    "capture_run_id": capture_run_id,
                    "capture_relative_path": capture_raw_path.name,
                    "capture_path": capture_raw_path.name,
                    "capture": capture,
                    "capture_schema_version": _HK_CAPTURE_V2_SCHEMA,
                    "capture_sha256": capture["capture_sha256"],
                    "capture_raw_sha256": capture_raw_sha256,
                    "codes": list(capture["codes"]),
                    "plate_response_counts": plate_response_counts,
                    "plate_response_sha256": plate_response_sha256,
                    "excluded_codes": evidence_codes,
                    "stale_codes": stale_codes,
                    "quote_status": capture["quote_status"],
                    "quote_errors": quote_errors,
                    "panel_status": capture["panel_status"],
                },
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        )
    _v4_scope["_LAST_HK_CAPTURE"] = capture
    if membership_ready_callback is not None:
        membership_ready_callback(capture)
    if snapshot_failure is not None:
        raise snapshot_failure
    if quote_errors:
        first_error = quote_errors[0]
        if first_error.startswith("HK exact-date coverage below gate:"):
            raise _v4_global(_v4_scope, 'SnapshotGateError')(first_error)
        if first_error.startswith("HK positive-trade coverage below gate:"):
            raise _v4_global(_v4_scope, 'SnapshotGateError')(first_error)
        raise _v4_global(_v4_scope, 'SnapshotGateError')(first_error)
    result = {
        "status": "READY",
        "target_date": target,
        "rows": rows,
        "universe_count": _v4_global(_v4_scope, 'len')(codes),
        "row_count": _v4_global(_v4_scope, 'len')(rows),
        "coverage_rate": coverage,
        "positive_volume_coverage_rate": positive_volume_coverage,
        "positive_turnover_coverage_rate": positive_turnover_coverage,
        "excluded_count": _v4_global(_v4_scope, 'len')(evidence_codes),
        "excluded_codes": evidence_codes_limited,
        "excluded_reasons": evidence_reasons,
        "source_sha256": source_sha,
        "sha256": source_sha,
        **_v4_global(_v4_scope, 'SAFETY_FLAGS'),
    }
    if capture_manifest_path is not None:
        result.update(
            {
                "capture_manifest_path": str(capture_manifest_path),
                "capture_raw_path": str(capture_raw_path),
                "capture_raw_sha256": capture_raw_sha256,
            }
        )
    return result

"""Materialize exact-date HK names with distinct universe and asset roots.

The shared producer historically assumed that immutable universe manifests and
mutable assets lived below one root.  The Mac runtime deliberately separates
those roots, so this bounded bridge verifies the exact universe from its
read-only root and publishes only the security-master asset to the shared
runtime store.
"""
from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
import math
import os
import tempfile
from datetime import datetime
from pathlib import Path
from pathlib import PurePosixPath
from typing import Any, Mapping

from infrastructure.isolated_package_loader import load_isolated_package_module


_CAPTURE_SCHEMA = "v3.macos.research_panel_hk_capture.v1"
_CAPTURE_SCHEMA_V2 = "v4.manager_hk_connect_capture.v2"
_CAPTURE_PLATES = ("HK.GangGuTong", "HK.LIST1922")
_SECURITY_FIELDS = (
    "code",
    "name",
    "outstanding_shares",
    "circular_market_val",
    "listing_date",
    "lot_size",
    "stock_owner",
    "stock_child_type",
    "sec_status",
)
_PANEL_FIELDS = (
    "trade_date",
    "code",
    "name",
    "open",
    "high",
    "low",
    "close",
    "volume",
    "turnover",
    "source",
)
_PANEL_NUMERIC_FIELDS = ("open", "high", "low", "close", "volume", "turnover")
_SECURITY_NUMERIC_FIELDS = ("outstanding_shares", "circular_market_val", "lot_size")
_NULLABLE_SECURITY_NUMERIC_FIELDS = frozenset(
    {"outstanding_shares", "circular_market_val"}
)
_HK_CODE_PATTERN = r"HK\.\d{5}"


def _canonical_sha(value: Any) -> str:
    encoded = json.dumps(
        value, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _is_sha256(value: Any) -> bool:
    return isinstance(value, str) and len(value) == 64 and all(
        character in "0123456789abcdefABCDEF" for character in value
    )


def _read_verified_hk_panel_authority(
    *,
    asset_root: Path,
    package_root: Path,
    authority: Mapping[str, Any],
    trade_date: str,
) -> str:
    """Read the updater's canonical panel manifest and verify its bytes."""

    root = Path(asset_root).expanduser().resolve()

    def resolve_asset_path(value: Any, label: str) -> tuple[Path, str]:
        if not isinstance(value, str) or not value.strip() or Path(value).is_absolute():
            raise ValueError(f"HK panel {label} path invalid")
        candidate = (root / value).resolve()
        try:
            relative = candidate.relative_to(root)
        except ValueError as error:
            raise ValueError(f"HK panel {label} path escapes asset root") from error
        if not candidate.is_file():
            raise ValueError(f"HK panel {label} artifact missing: {candidate}")
        return candidate, relative.as_posix()

    try:
        pointer = json.loads((root / "panel_latest.json").read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise ValueError("HK panel authority pointer unreadable") from error
    if not isinstance(pointer, Mapping):
        raise ValueError("HK panel authority pointer invalid")
    manifest_path, manifest_relative = resolve_asset_path(pointer.get("manifest_relative"), "manifest")
    authority_relative = authority.get("manifest_relative")
    if not isinstance(authority_relative, str):
        raise ValueError("HK panel authority manifest identity missing")
    authority_manifest_path, authority_manifest_relative = resolve_asset_path(authority_relative, "updater manifest")
    if authority_manifest_path != manifest_path or authority_manifest_relative != manifest_relative:
        raise ValueError("HK panel authority manifest identity mismatch")
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise ValueError("HK panel authority manifest unreadable") from error
    if not isinstance(manifest, Mapping):
        raise ValueError("HK panel authority manifest invalid")

    try:
        from infrastructure import isolated_package_loader

        reader_module = isolated_package_loader.load_isolated_package_module(
            Path(package_root),
            package_directory="shared_data",
            module_leaf="hk_0_2",
            namespace_prefix="v35_hk_daily_panel_authority",
        )
        assets = getattr(reader_module, "load_frozen_hk_0_2_assets")(root)
    except Exception as error:
        raise ValueError("HK panel authority reader failed") from error
    trusted_manifest = getattr(assets, "panel_manifest", None)
    trusted_panel_path = getattr(assets, "panel_path", None)
    if not isinstance(trusted_manifest, Mapping) or not isinstance(trusted_panel_path, (str, Path)):
        raise ValueError("HK panel authority reader returned invalid identity")
    if _canonical_sha(dict(trusted_manifest)) != _canonical_sha(dict(manifest)):
        raise ValueError("HK panel authority manifest identity changed")
    if manifest.get("asset_schema_version") not in {
        "v3_shared_data.hk_0_2_panel_asset.v1",
        "v3_shared_data.hk_0_2_panel_asset.v2",
    }:
        raise ValueError("HK panel authority manifest schema invalid")
    if manifest.get("panel_max_date") != trade_date:
        raise ValueError("HK panel authority manifest target date mismatch")
    if manifest.get("production_allowed") is not False or any(
        name in manifest and manifest.get(name) is not False
        for name in ("buy_gate_updated", "orders_sent")
    ):
        raise ValueError("HK panel authority manifest safety contract invalid")
    panel_path, _panel_relative = resolve_asset_path(manifest.get("panel_relative"), "panel")
    if Path(trusted_panel_path).expanduser().resolve() != panel_path:
        raise ValueError("HK panel authority panel identity mismatch")
    manifest_panel_sha = manifest.get("panel_sha256")
    if not _is_sha256(manifest_panel_sha):
        raise ValueError("HK panel manifest SHA invalid")
    actual_panel_sha = hashlib.sha256(panel_path.read_bytes()).hexdigest()
    if actual_panel_sha.lower() != str(manifest_panel_sha).lower() or actual_panel_sha.lower() != str(authority.get("panel_sha256")).lower():
        raise ValueError("HK panel SHA does not match manifest artifact")
    try:
        pointer_after = json.loads((root / "panel_latest.json").read_text(encoding="utf-8"))
        manifest_after = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise ValueError("HK panel authority identity changed") from error
    if (
        not isinstance(pointer_after, Mapping)
        or pointer_after.get("manifest_relative") != pointer.get("manifest_relative")
        or not isinstance(manifest_after, Mapping)
        or _canonical_sha(dict(manifest_after)) != _canonical_sha(dict(manifest))
    ):
        raise ValueError("HK panel authority identity changed")
    if hashlib.sha256(panel_path.read_bytes()).hexdigest() != actual_panel_sha:
        raise ValueError("HK panel SHA changed during authority binding")
    return actual_panel_sha


def _valid_hk_code(value: Any) -> bool:
    import re

    return isinstance(value, str) and re.fullmatch(_HK_CODE_PATTERN, value) is not None


def _non_placeholder_name(value: Any, code: str) -> bool:
    name = str(value or "").strip()
    return bool(name) and name.upper() != code and name not in {
        code[3:],
        f"{code[3:]}.HK",
        f"{code[3:]}.HK_CONNECT",
    }


def _value_is_missing(value: Any) -> bool:
    return value is None or (isinstance(value, str) and not value.strip())


def _value_is_finite_number(value: Any) -> bool:
    if isinstance(value, bool) or _value_is_missing(value):
        return False
    try:
        return math.isfinite(float(value))
    except (TypeError, ValueError, OverflowError):
        return False


def _value_is_numeric_nan(value: Any) -> bool:
    """Return whether a non-string value is the numeric NaN sentinel."""

    if value is None or isinstance(value, (bool, str, bytes, bytearray)):
        return False
    try:
        return math.isnan(float(value))
    except (TypeError, ValueError, OverflowError):
        return False


def _validate_complete_row(
    row: Mapping[str, Any],
    *,
    fields: tuple[str, ...],
    numeric_fields: tuple[str, ...],
    label: str,
    nullable_fields: frozenset[str] = frozenset(),
    nullable_numeric_fields: frozenset[str] = frozenset(),
) -> None:
    missing_fields = [field for field in fields if field not in row]
    if missing_fields:
        raise ValueError(f"{label} fields missing: {', '.join(missing_fields)}")
    missing_values = [
        field
        for field in fields
        if field not in nullable_fields and _value_is_missing(row.get(field))
    ]
    if missing_values:
        raise ValueError(f"{label} value missing: {', '.join(missing_values)}")
    invalid_numbers = [
        field
        for field in numeric_fields
        if not (
            field in nullable_fields
            and (
                _value_is_missing(row.get(field))
                or (
                    field in nullable_numeric_fields
                    and _value_is_numeric_nan(row.get(field))
                )
            )
        )
        and not _value_is_finite_number(row.get(field))
    ]
    if invalid_numbers:
        raise ValueError(f"{label} numeric value invalid: {', '.join(invalid_numbers)}")
    negative_numbers = [
        field
        for field in numeric_fields
        if _value_is_finite_number(row.get(field)) and float(row.get(field)) < 0
    ]
    if negative_numbers:
        raise ValueError(f"{label} numeric value invalid: {', '.join(negative_numbers)}")


def _validate_security_master_rows(
    rows: Mapping[str, Mapping[str, Any]], *, expected_codes: list[str] | tuple[str, ...] | set[str]
) -> None:
    if not isinstance(rows, Mapping):
        raise ValueError("HK security-master rows invalid")
    expected = list(expected_codes)
    if set(rows) != set(expected):
        raise ValueError("HK security-master rows coverage mismatch")
    for code in expected:
        row = rows.get(code)
        if not isinstance(row, Mapping):
            raise ValueError(f"HK security-master row invalid: {code}")
        _validate_complete_row(
            row,
            fields=_SECURITY_FIELDS,
            numeric_fields=_SECURITY_NUMERIC_FIELDS,
            label=f"HK security-master {code}",
            nullable_fields=frozenset(
                {"stock_child_type", "outstanding_shares", "circular_market_val"}
            ),
            nullable_numeric_fields=_NULLABLE_SECURITY_NUMERIC_FIELDS,
        )
        if row.get("code") != code:
            raise ValueError(f"HK security-master row code mismatch: {code}")
        if not _non_placeholder_name(row.get("name"), code):
            raise ValueError(f"HK security-master name missing: {code}")


def _normalized_master_value(field: str, value: Any) -> object:
    if field in {"outstanding_shares", "circular_market_val", "lot_size"}:
        if value in (None, ""):
            return ""
        try:
            return float(value)
        except (TypeError, ValueError):
            return str(value).strip()
    return str(value or "").strip()


def _capture_rows_match(
    existing: Mapping[str, Mapping[str, Any]],
    captured: list[Mapping[str, Any]],
) -> bool:
    for expected in captured:
        code = str(expected.get("code") or "")
        current = existing.get(code)
        if not isinstance(current, Mapping):
            return False
        if any(
            _normalized_master_value(field, current.get(field))
            != _normalized_master_value(field, expected.get(field))
            for field in _SECURITY_FIELDS
        ):
            return False
    return True


def _panel_capture_binding_sha256(
    capture: Mapping[str, Any], panel_sha256: str
) -> str:
    if not _is_sha256(panel_sha256):
        raise ValueError("HK panel SHA invalid")
    return _canonical_sha(
        {
            "capture_sha256": capture["capture_sha256"],
            "codes": capture["codes"],
            "rows": capture["rows"],
            "panel_sha256": panel_sha256,
        }
    )


def _validated_capture(
    capture: Mapping[str, Any], *, trade_date: str, panel_sha256: str | None
) -> dict[str, Any]:
    if not isinstance(capture, Mapping):
        raise ValueError("HK panel capture envelope invalid")
    envelope = dict(capture)
    capture_schema = envelope.get("schema_version")
    if capture_schema not in {_CAPTURE_SCHEMA, _CAPTURE_SCHEMA_V2}:
        raise ValueError("HK panel capture schema mismatch")
    if capture_schema == _CAPTURE_SCHEMA_V2:
        contract, _contract_owner = _load_hk_connect_v2_contract()
        try:
            contract.validate_captured_hk_connect_membership_v2(
                envelope, trade_date=trade_date
            )
        except (TypeError, ValueError) as error:
            raise ValueError("HK panel capture v2 membership invalid") from error
    if envelope.get("target_date") != trade_date:
        raise ValueError("HK panel capture target date mismatch")
    if list(envelope.get("plates") or []) != list(_CAPTURE_PLATES):
        raise ValueError("HK panel capture plates mismatch")
    if any(envelope.get(name) is not False for name in ("production_allowed", "buy_gate_updated", "orders_sent")):
        raise ValueError("HK panel capture safety contract invalid")
    if panel_sha256 is not None and not _is_sha256(panel_sha256):
        raise ValueError("HK panel SHA invalid")

    codes = envelope.get("codes")
    if not isinstance(codes, list) or not codes or any(not _valid_hk_code(code) for code in codes):
        raise ValueError("HK panel capture codes invalid")
    if codes != sorted(codes) or len(codes) != len(set(codes)):
        raise ValueError("HK panel capture codes duplicate or unsorted")

    rows = envelope.get("rows")
    if not isinstance(rows, list) or not rows:
        raise ValueError("HK panel capture rows missing")

    source_payload = envelope.get("source_payload")
    source_sha256 = envelope.get("source_sha256")
    if not isinstance(source_payload, Mapping) or not _is_sha256(source_sha256):
        raise ValueError("HK panel capture source hash missing")
    if source_payload.get("target_date") != trade_date:
        raise ValueError("HK panel capture source target date mismatch")
    if list(source_payload.get("plates") or []) != list(_CAPTURE_PLATES):
        raise ValueError("HK panel capture source plates mismatch")
    if source_payload.get("rows") != rows or _canonical_sha(source_payload) != source_sha256:
        raise ValueError("HK panel capture source hash mismatch")

    excluded_codes = source_payload.get("excluded_codes")
    if not isinstance(excluded_codes, list) or any(
        not _valid_hk_code(code) for code in excluded_codes
    ):
        raise ValueError("HK panel capture excluded codes invalid")
    if excluded_codes != sorted(excluded_codes):
        raise ValueError("HK panel capture excluded codes unsorted")
    if len(excluded_codes) != len(set(excluded_codes)):
        raise ValueError("HK panel capture excluded codes duplicate")
    if any(code not in codes for code in excluded_codes):
        raise ValueError("HK panel capture excluded code outside universe")
    excluded_count = source_payload.get("excluded_count")
    if (
        isinstance(excluded_count, bool)
        or not isinstance(excluded_count, int)
        or excluded_count != len(excluded_codes)
    ):
        raise ValueError("HK panel capture excluded count mismatch")
    excluded_reasons = source_payload.get("excluded_reasons")
    if not isinstance(excluded_reasons, Mapping):
        raise ValueError("HK panel capture excluded reason/quarantine evidence missing")
    if set(excluded_reasons) != set(excluded_codes):
        raise ValueError("HK panel capture excluded reason/quarantine set mismatch")
    for code in excluded_codes:
        reasons = excluded_reasons.get(code)
        if not isinstance(reasons, list) or not reasons or any(
            not isinstance(reason, str) or not reason.strip() for reason in reasons
        ):
            raise ValueError(
                f"HK panel capture excluded reason/quarantine missing: {code}"
            )

    row_codes: list[str] = []
    for row in rows:
        if not isinstance(row, Mapping):
            raise ValueError("HK panel capture row invalid")
        _validate_complete_row(
            row,
            fields=_PANEL_FIELDS,
            numeric_fields=_PANEL_NUMERIC_FIELDS,
            label="HK panel capture panel",
        )
        if row.get("trade_date") != trade_date:
            raise ValueError("HK panel capture row date mismatch")
        code = row.get("code")
        if not _valid_hk_code(code) or code not in codes:
            raise ValueError("HK panel capture row code outside universe")
        if not _non_placeholder_name(row.get("name"), code):
            raise ValueError(f"HK panel capture panel name missing: {code}")
        row_codes.append(code)
    if len(row_codes) != len(set(row_codes)):
        raise ValueError("HK panel capture rows duplicate")
    expected_row_codes = set(codes) - set(excluded_codes)
    if set(row_codes) != expected_row_codes:
        raise ValueError("HK panel capture rows coverage mismatch")

    security_rows = envelope.get("security_master_rows")
    if not isinstance(security_rows, list) or len(security_rows) != len(codes):
        raise ValueError("HK security-master capture coverage mismatch")
    security_codes: list[str] = []
    for row in security_rows:
        if not isinstance(row, Mapping):
            raise ValueError("HK security-master capture row invalid")
        _validate_complete_row(
            row,
            fields=_SECURITY_FIELDS,
            numeric_fields=_SECURITY_NUMERIC_FIELDS,
            label="HK security-master capture",
            nullable_fields=frozenset(
                {"stock_child_type", "outstanding_shares", "circular_market_val"}
            ),
            nullable_numeric_fields=_NULLABLE_SECURITY_NUMERIC_FIELDS,
        )
        code = row.get("code")
        if not _valid_hk_code(code) or code not in codes:
            raise ValueError("HK security-master capture code outside universe")
        if not _non_placeholder_name(row.get("name"), code):
            raise ValueError(f"HK security-master capture name missing: {code}")
        security_codes.append(code)
    if security_codes != codes or len(security_codes) != len(set(security_codes)):
        raise ValueError("HK security-master capture codes duplicate or incomplete")

    capture_digest = envelope.get("capture_sha256")
    if not _is_sha256(capture_digest):
        raise ValueError("HK panel capture hash missing")
    digest_payload = dict(envelope)
    digest_payload.pop("capture_sha256", None)
    if _canonical_sha(digest_payload) != capture_digest:
        raise ValueError("HK panel capture hash mismatch")
    return envelope


def _load_hk_connect_v2_contract():
    """Load the adjacent, exact candidate pure v2 contract by file identity."""
    app_root = Path(__file__).resolve().parents[1]
    path = app_root / "stage_center" / "hk_universe_preflight.py"
    if path.is_symlink() or not path.is_file():
        raise ValueError("HK Connect v2 contract source missing or symlinked")
    source_sha256 = hashlib.sha256(path.read_bytes()).hexdigest()
    spec = importlib.util.spec_from_file_location(
        "_hk_connect_v2_contract_" + source_sha256, path
    )
    if spec is None or spec.loader is None:
        raise ValueError("HK Connect v2 contract loader unavailable")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    if (
        Path(module.__file__).resolve() != path.resolve()
        or hashlib.sha256(path.read_bytes()).hexdigest() != source_sha256
        or not callable(getattr(module, "validate_captured_hk_connect_membership_v2", None))
        or not callable(getattr(module, "build_captured_hk_connect_authority_v2", None))
    ):
        raise ValueError("HK Connect v2 contract source identity changed")
    owner = {
        "code_ref": "stage_center/hk_universe_preflight.py",
        "code_sha256": source_sha256,
        "role": "PURE_CAPTURED_HK_CONNECT_CONTRACT_V2",
    }
    return module, owner


def _authority_path(root: Path, relative: str) -> Path:
    """Resolve one normalized authority path below the existing store root."""
    if not isinstance(relative, str) or not relative or "\\" in relative:
        raise ValueError("HK Connect authority path invalid")
    path = PurePosixPath(relative)
    if path.is_absolute() or path.as_posix() != relative or any(
        part in {"", ".", ".."} for part in path.parts
    ):
        raise ValueError("HK Connect authority path invalid")
    real_root = root.expanduser().resolve()
    candidate = real_root
    for part in path.parts:
        candidate = candidate / part
        if candidate.is_symlink():
            raise ValueError("HK Connect authority path symlink")
    resolved = candidate.resolve()
    try:
        resolved.relative_to(real_root)
    except ValueError as error:
        raise ValueError("HK Connect authority path escapes store root") from error
    return candidate


def _create_immutable_authority_file(path: Path, payload: bytes) -> bool:
    """Create exact authority bytes without ever replacing an existing file."""
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.is_symlink():
        raise ValueError("HK Connect authority file symlink")
    if path.exists():
        if not path.is_file() or path.read_bytes() != payload:
            raise ValueError(f"HK Connect authority immutable conflict: {path.name}")
        return False
    fd, temporary = tempfile.mkstemp(
        prefix=f".{path.name}.", suffix=".tmp", dir=path.parent
    )
    temporary_path = Path(temporary)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(payload)
            stream.flush()
            os.fsync(stream.fileno())
        try:
            os.link(temporary_path, path)
            return True
        except FileExistsError:
            if path.is_symlink() or not path.is_file() or path.read_bytes() != payload:
                raise ValueError(f"HK Connect authority immutable conflict: {path.name}")
            return False
    finally:
        try:
            temporary_path.unlink()
        except FileNotFoundError:
            pass


def _publish_captured_hk_connect_authority_v2(
    *, store_root: Path, trade_date: str, capture: Mapping[str, Any]
) -> dict[str, Any]:
    """Publish one captured-input v2 chain within the existing store root."""
    contract, contract_owner = _load_hk_connect_v2_contract()
    producer_owner = capture.get("producer_owner")
    if not isinstance(producer_owner, Mapping):
        raise ValueError("HK Connect v2 producer owner missing")
    built = contract.build_captured_hk_connect_authority_v2(
        capture,
        trade_date=trade_date,
        producer_owner=producer_owner,
        contract_owner=contract_owner,
    )
    root = store_root.expanduser().resolve()
    file_payloads = [
        (built["paths"]["artifact_relative"], built["artifact_bytes"]),
        (built["paths"]["manifest_relative"], built["manifest_bytes"]),
        (built["paths"]["receipt_relative"], built["receipt_bytes"]),
        (built["capture_relative"], built["capture_bytes"]),
        (built["paths"]["current_relative"], built["current_bytes"]),
    ]
    written = {}
    for relative, encoded in file_payloads:
        path = _authority_path(root, relative)
        created = _create_immutable_authority_file(path, encoded)
        actual = path.read_bytes()
        if actual != encoded:
            raise ValueError(f"HK Connect authority readback mismatch: {relative}")
        written[relative] = {
            "sha256": hashlib.sha256(actual).hexdigest(),
            "size_bytes": len(actual),
            "created": created,
        }

    # Availability is witnessed only after every upstream immutable byte has
    # been read back from disk. Existing publication bytes remain immutable.
    publication_relative = built["publication_relative"]
    publication_path = _authority_path(root, publication_relative)
    if publication_path.exists():
        try:
            publication = json.loads(publication_path.read_bytes().decode("utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as error:
            raise ValueError("HK Connect v2 publication receipt unreadable") from error
        if not isinstance(publication, Mapping):
            raise ValueError("HK Connect v2 publication receipt invalid")
        publication_material = dict(publication)
        publication_digest = publication_material.pop("publication_sha256", None)
        if not _is_sha256(publication_digest) or _canonical_sha(publication_material) != publication_digest:
            raise ValueError("HK Connect v2 publication receipt hash mismatch")
        expected_identity = {
            "schema_version": contract.HK_CONNECT_PUBLICATION_SCHEMA_V2,
            "status": "READY",
            "target_date": trade_date,
            "run_id": built["run_id"],
            "capture_run_id": capture["capture_run_id"],
            "capture_sha256": capture["capture_sha256"],
            "artifact_sha256": built["artifact_sha256"],
            "current_sha256": built["current_sha256"],
            "producer_owner": dict(producer_owner),
            "contract_owner": contract_owner,
            **contract.SAFETY_FLAGS,
        }
        if any(publication.get(key) != value for key, value in expected_identity.items()):
            raise ValueError("HK Connect v2 publication receipt identity mismatch")
        available_at = publication.get("available_at")
        try:
            available_dt = datetime.fromisoformat(str(available_at).replace("Z", "+00:00"))
        except (TypeError, ValueError) as error:
            raise ValueError("HK Connect v2 publication availability invalid") from error
        if available_dt.tzinfo is None:
            raise ValueError("HK Connect v2 publication availability is naive")
    else:
        publication = {
            "schema_version": contract.HK_CONNECT_PUBLICATION_SCHEMA_V2,
            "status": "READY",
            "target_date": trade_date,
            "effective_date": trade_date,
            "trade_date": trade_date,
            "source_date": trade_date,
            "market": "HK_CONNECT",
            "scope": "FULL_MARKET",
            "run_id": built["run_id"],
            "publication_relative": publication_relative,
            "available_at": datetime.now().astimezone().isoformat(timespec="microseconds"),
            "acquired_at": capture["acquired_at"],
            "capture_run_id": capture["capture_run_id"],
            "capture_sha256": capture["capture_sha256"],
            "artifact_relative": built["paths"]["artifact_relative"],
            "artifact_sha256": built["artifact_sha256"],
            "manifest_relative": built["paths"]["manifest_relative"],
            "receipt_relative": built["paths"]["receipt_relative"],
            "current_relative": built["paths"]["current_relative"],
            "current_sha256": built["current_sha256"],
            "workload_id": producer_owner.get("workload_id"),
            "producer_owner": dict(producer_owner),
            "contract_owner": contract_owner,
            "forward_source_set": producer_owner.get("forward_source_set"),
            "forward_source_set_sha256": producer_owner.get("forward_source_set_sha256"),
            **contract.SAFETY_FLAGS,
        }
        publication["publication_sha256"] = _canonical_sha(publication)
        publication_bytes = contract._canonical_json_line(publication)
        _create_immutable_authority_file(publication_path, publication_bytes)
        if publication_path.read_bytes() != publication_bytes:
            raise ValueError("HK Connect v2 publication receipt readback mismatch")

    return {
        "status": "READY",
        "run_id": built["run_id"],
        "trade_date": trade_date,
        "artifact_sha256": built["artifact_sha256"],
        "current_sha256": built["current_sha256"],
        "capture_run_id": capture["capture_run_id"],
        "capture_sha256": capture["capture_sha256"],
        "available_at": publication["available_at"],
        "publication_relative": publication_relative,
        "written_files": written,
        **contract.SAFETY_FLAGS,
    }


def _capture_result(
    *,
    capture: Mapping[str, Any],
    trade_date: str,
    panel_sha256: str | None,
    rows: Mapping[str, Mapping[str, Any]],
    manifest: Mapping[str, Any],
    reused: bool,
    run_id: Any,
    artifact_sha256: Any,
    manifest_sha256: Any,
) -> dict[str, object]:
    result = {
        "ok": True,
        "status": "READY",
        "reused": reused,
        "trade_date": trade_date,
        "row_count": len(rows),
        "run_id": run_id,
        "security_master_run_id": run_id,
        "universe_codes_sha256": _canonical_sha(capture["codes"]),
        "capture_sha256": capture["capture_sha256"],
        "source_sha256": capture["source_sha256"],
        "panel_sha256": panel_sha256,
        "panel_capture_binding_sha256": _panel_capture_binding_sha256(
            capture, panel_sha256
        ),
        "security_master_artifact_sha256": artifact_sha256,
        "security_master_manifest_sha256": manifest_sha256,
        "production_allowed": False,
        "buy_gate_updated": False,
        "orders_sent": False,
    }
    return result


def ensure_hk_security_master(
    *,
    store_root: Path,
    universe_root: Path,
    shared_package_root: Path,
    trade_date: str,
    futu_python: Path,
    capture: Mapping[str, Any] | None = None,
    panel_sha256: str | None = None,
    panel_binding_sha256: str | None = None,
    membership_only: bool = False,
    reuse_only: bool = False,
) -> dict[str, object]:
    package_root = shared_package_root.expanduser().resolve()
    if not package_root.is_dir():
        raise ValueError(f"shared package root missing: {package_root}")
    if membership_only:
        if capture is None or panel_sha256 is not None or panel_binding_sha256 is not None:
            raise ValueError("HK membership-only ensure requires capture without panel binding")
        contract, _contract_owner = _load_hk_connect_v2_contract()
        try:
            validated_membership = contract.validate_captured_hk_connect_membership_v2(
                capture, trade_date=trade_date
            )
        except (TypeError, ValueError) as error:
            raise ValueError("HK membership-only capture v2 invalid") from error
        authority = _publish_captured_hk_connect_authority_v2(
            store_root=store_root.expanduser().resolve(),
            trade_date=trade_date,
            capture=capture,
        )
        return {
            "ok": True,
            "status": authority.get("status", "READY"),
            "trade_date": trade_date,
            "row_count": validated_membership["code_count"],
            "capture_sha256": validated_membership["capture_sha256"],
            "source_sha256": validated_membership["source_sha256"],
            "panel_sha256": None,
            "panel_capture_binding_sha256": None,
            "universe_authority": authority,
            "production_allowed": False,
            "buy_gate_updated": False,
            "orders_sent": False,
        }
    validated_capture = (
        _validated_capture(capture, trade_date=trade_date, panel_sha256=panel_sha256)
        if capture is not None
        else None
    )
    expected_panel_binding_sha256: str | None = None
    if validated_capture is not None:
        if not _is_sha256(panel_sha256):
            raise ValueError("HK panel SHA missing")
        expected_panel_binding_sha256 = _panel_capture_binding_sha256(
            validated_capture, panel_sha256
        )
        if panel_binding_sha256 is not None:
            if not _is_sha256(panel_binding_sha256):
                raise ValueError("HK panel capture binding SHA invalid")
            if panel_binding_sha256 != expected_panel_binding_sha256:
                raise ValueError("HK panel capture binding SHA mismatch")

    acquire_module = load_isolated_package_module(
        package_root,
        package_directory="scripts",
        module_leaf="acquire_hk_security_master",
        namespace_prefix="v35_hk_security_master_acquire",
    )
    load_verified_hk_security_master = getattr(
        acquire_module, "load_verified_hk_security_master"
    )
    store_error = getattr(acquire_module, "StoreError")
    if not isinstance(store_error, type) or not issubclass(store_error, Exception):
        raise ValueError("trusted acquire module has invalid StoreError")

    if validated_capture is not None:
        codes = list(validated_capture["codes"])
        try:
            rows, manifest = load_verified_hk_security_master(store_root, trade_date)
        except store_error:
            rows, manifest = {}, {}
        existing_is_valid = True
        if rows:
            try:
                _validate_security_master_rows(rows, expected_codes=codes)
            except ValueError:
                existing_is_valid = False
        if (
            existing_is_valid
            and
            manifest.get("universe_codes_sha256") == _canonical_sha(codes)
            and manifest.get("valuation_eligibility_field") == "circular_market_val"
            and set(rows) == set(codes)
            and _capture_rows_match(rows, validated_capture["security_master_rows"])
        ):
            result = _capture_result(
                capture=validated_capture,
                trade_date=trade_date,
                panel_sha256=panel_sha256,
                rows=rows,
                manifest=manifest,
                reused=True,
                run_id=manifest.get("run_id"),
                artifact_sha256=manifest.get("artifact_sha256"),
                manifest_sha256=_canonical_sha(manifest),
            )
            if validated_capture.get("schema_version") == _CAPTURE_SCHEMA_V2:
                result["universe_authority"] = _publish_captured_hk_connect_authority_v2(
                    store_root=store_root,
                    trade_date=trade_date,
                    capture=validated_capture,
                )
            return result

        publish_hk_security_master = getattr(acquire_module, "publish_hk_security_master")
        _validate_security_master_rows(
            {str(row["code"]): row for row in validated_capture["security_master_rows"]},
            expected_codes=codes,
        )
        published = publish_hk_security_master(
            store_root,
            trade_date=trade_date,
            rows=validated_capture["security_master_rows"],
            universe_codes_sha256=_canonical_sha(codes),
            captured_at=datetime.now().astimezone().isoformat(timespec="seconds"),
        )
        published_manifest = published.get("manifest")
        if not isinstance(published_manifest, Mapping):
            published_manifest = {}
        result = _capture_result(
            capture=validated_capture,
            trade_date=trade_date,
            panel_sha256=panel_sha256,
            rows={str(row["code"]): row for row in validated_capture["security_master_rows"]},
            manifest=published_manifest,
            reused=False,
            run_id=published.get("run_id"),
            artifact_sha256=published.get("artifact_sha256"),
            manifest_sha256=published.get("manifest_sha256") or _canonical_sha(published_manifest),
        )
        if validated_capture.get("schema_version") == _CAPTURE_SCHEMA_V2:
            result["universe_authority"] = _publish_captured_hk_connect_authority_v2(
                store_root=store_root,
                trade_date=trade_date,
                capture=validated_capture,
            )
        return result

    resolve_stage_universe = getattr(acquire_module, "resolve_stage_universe", None)

    try:
        if not callable(resolve_stage_universe):
            raise ValueError("trusted acquire module has no universe resolver")
        universe = resolve_stage_universe(universe_root, trade_date, "HK_CONNECT")
        universe_codes = list(universe.codes)
        universe_codes_sha256 = universe.codes_sha256
    except Exception as resolution_error:
        # The exact-date panel may seed a reuse/collection only when the
        # legacy authority's current pointer is explicitly absent.  Any
        # checksum, schema, scope, date, or tamper error is authoritative and
        # must fail closed rather than being hidden by a fallback.
        if not (
            isinstance(resolution_error, ValueError)
            and str(resolution_error) == "HK_CONNECT authority current pointer missing"
        ):
            raise
        panel_codes_loader = getattr(acquire_module, "_load_exact_date_hk_panel_codes", None)
        if not callable(panel_codes_loader):
            raise resolution_error
        try:
            universe_codes, universe_codes_sha256 = panel_codes_loader(store_root, trade_date)
        except Exception:
            raise resolution_error
    try:
        rows, manifest = load_verified_hk_security_master(store_root, trade_date)
    except store_error:
        rows, manifest = {}, {}
    if (
        manifest.get("universe_codes_sha256") == universe_codes_sha256
        and manifest.get("valuation_eligibility_field") == "circular_market_val"
        and set(rows) == set(universe_codes)
    ):
        _validate_security_master_rows(rows, expected_codes=universe_codes)
        result: dict[str, object] = {
            "ok": True,
            "status": "READY",
            "reused": True,
            "trade_date": trade_date,
            "row_count": len(rows),
            "run_id": manifest.get("run_id"),
            "universe_codes_sha256": universe_codes_sha256,
            "production_allowed": False,
            "buy_gate_updated": False,
            "orders_sent": False,
        }
        if reuse_only:
            result.update(
                {
                    "security_master_run_id": manifest.get("run_id"),
                    "security_master_artifact_sha256": manifest.get("artifact_sha256"),
                    "security_master_manifest_sha256": _canonical_sha(manifest),
                }
            )
        return result

    if reuse_only:
        raise store_error(
            f"HK security-master exact-date authority unavailable for reuse: {trade_date}"
        )

    publish_hk_security_master = getattr(acquire_module, "publish_hk_security_master")
    collect_futu_hk_security_master = getattr(
        acquire_module, "collect_futu_hk_security_master"
    )
    collected = collect_futu_hk_security_master(futu_python, list(universe_codes))
    collected_rows = {
        str(row.get("code") or ""): row
        for row in collected
        if isinstance(row, Mapping)
    }
    _validate_security_master_rows(collected_rows, expected_codes=universe_codes)
    published = publish_hk_security_master(
        store_root,
        trade_date=trade_date,
        rows=collected,
        universe_codes_sha256=universe_codes_sha256,
        captured_at=datetime.now().astimezone().isoformat(timespec="seconds"),
    )
    return {
        "ok": True,
        "status": "READY",
        "reused": False,
        "trade_date": trade_date,
        "row_count": published["row_count"],
        "run_id": published["run_id"],
        "universe_codes_sha256": universe_codes_sha256,
        "production_allowed": False,
        "buy_gate_updated": False,
        "orders_sent": False,
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--store-root", required=True, type=Path)
    parser.add_argument("--universe-root", required=True, type=Path)
    parser.add_argument("--shared-package-root", required=True, type=Path)
    parser.add_argument("--trade-date", required=True)
    parser.add_argument("--futu-python", required=True, type=Path)
    parser.add_argument(
        "--reuse-only",
        action="store_true",
        help="Reuse an exact dated master; never invoke a Futu collector",
    )
    args = parser.parse_args(argv)
    try:
        result = ensure_hk_security_master(
            store_root=args.store_root,
            universe_root=args.universe_root,
            shared_package_root=args.shared_package_root,
            trade_date=args.trade_date,
            futu_python=args.futu_python,
            reuse_only=args.reuse_only,
        )
    except Exception as error:  # scheduler boundary: emit one fail-closed JSON result
        result = {
            "ok": False,
            "status": "FAILED",
            "error": f"{type(error).__name__}: {error}",
            "production_allowed": False,
            "buy_gate_updated": False,
            "orders_sent": False,
        }
    print(json.dumps(result, ensure_ascii=False, sort_keys=True))
    return 0 if result.get("ok") else 1


if __name__ == "__main__":
    raise SystemExit(main())

"""HK capture, manifest, panel, and security-master authority gate."""
from __future__ import annotations

from ._namespace import read_global as _v4_global


def run_hk_capture_gate(
    _v4_scope,
    /,
    *,
    target_date,
    args,
    authority_paths,
    python_executable,
):
    """Run the existing HK owner chain against one immutable Futu capture."""
    target = target_date
    capture_manifest_path = args.receipt_root / "hk_capture" / target / (
        f"{target}-{_v4_global(_v4_scope, 'os').getpid()}-"
        f"{_v4_global(_v4_scope, 'os').urandom(12).hex()}.json"
    )
    env = _v4_global(_v4_scope, 'os').environ
    ensure_module = _v4_global(_v4_scope, 'importlib').import_module(
        "ops.ensure_hk_security_master"
    )
    asset_root = args.hk_asset_root.expanduser().resolve()
    store_root = asset_root.parent.parent
    package_root = _v4_global(_v4_scope, 'Path')(
        authority_paths["--hk-updater-script"]
    ).expanduser().resolve().parents[1]
    membership_result = {}

    def publish_membership(capture):
        membership_result.update(ensure_module.ensure_hk_security_master(
            store_root=store_root,
            universe_root=store_root,
            shared_package_root=package_root,
            trade_date=target,
            futu_python=python_executable,
            capture=capture,
            membership_only=True,
        ))

    previous_capture_path = env.get("V35_HK_CAPTURE_PATH")
    previous_capture_run_id = env.get("V35_HK_CAPTURE_RUN_ID")
    env["V35_HK_CAPTURE_PATH"] = str(capture_manifest_path)
    env["V35_HK_CAPTURE_RUN_ID"] = capture_manifest_path.stem
    try:
        collector = _v4_global(_v4_scope, 'importlib').import_module(
            "ops._macos_research_panel_daily_parts.hk_market_capture"
        )
        collected = collector._collect_hk_futu_rows_body(
            _v4_scope,
            target,
            context_factory=None,
            batch_size=200,
            minimum_universe_count=600,
            required_coverage_ratio=0.0,
            membership_ready_callback=publish_membership,
        )
    finally:
        if previous_capture_path is None:
            env.pop("V35_HK_CAPTURE_PATH", None)
        else:
            env["V35_HK_CAPTURE_PATH"] = previous_capture_path
        if previous_capture_run_id is None:
            env.pop("V35_HK_CAPTURE_RUN_ID", None)
        else:
            env["V35_HK_CAPTURE_RUN_ID"] = previous_capture_run_id

    reported_capture_path = (
        collected.get("capture_manifest_path")
        if _v4_global(_v4_scope, 'isinstance')(collected, _v4_global(_v4_scope, 'Mapping'))
        else None
    )
    if not reported_capture_path:
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK collector did not return its exact capture manifest path"
        )
    reported_capture_path = _v4_global(_v4_scope, 'Path')(str(reported_capture_path)).expanduser()
    if reported_capture_path.is_symlink():
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK capture manifest path must not be a symlink"
        )
    capture_manifest_path = reported_capture_path.resolve()
    try:
        capture_manifest_path.relative_to(args.receipt_root.expanduser().resolve())
    except ValueError as error:
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK collector returned a capture path outside receipt root"
        ) from error

    capture = None
    try:
        envelope = _v4_global(_v4_scope, 'json').loads(
            capture_manifest_path.read_bytes().decode("utf-8-sig")
        )
        envelope_data = envelope if _v4_global(_v4_scope, 'isinstance')(
            envelope, _v4_global(_v4_scope, 'Mapping')
        ) else {}
        candidate = envelope_data.get("capture")
        if not _v4_global(_v4_scope, 'isinstance')(
            candidate, _v4_global(_v4_scope, 'Mapping')
        ):
            raise _v4_global(_v4_scope, 'SnapshotGateError')(
                "HK capture manifest capture payload is invalid"
            )
        raw_reference = envelope_data.get("capture_relative_path") or envelope_data.get(
            "capture_path"
        )
        if (
            not _v4_global(_v4_scope, 'isinstance')(raw_reference, _v4_global(_v4_scope, 'str'))
            or not raw_reference
            or _v4_global(_v4_scope, 'Path')(raw_reference).is_absolute()
        ):
            raise _v4_global(_v4_scope, 'SnapshotGateError')(
                "HK capture raw path must be relative"
            )
        raw_unresolved = capture_manifest_path.parent / raw_reference
        if raw_unresolved.is_symlink():
            raise _v4_global(_v4_scope, 'SnapshotGateError')(
                "HK capture raw path must not be a symlink"
            )
        raw_path = raw_unresolved.resolve()
        try:
            raw_path.relative_to(capture_manifest_path.parent.resolve())
        except ValueError as error:
            raise _v4_global(_v4_scope, 'SnapshotGateError')(
                "HK capture raw path escapes manifest root"
            ) from error
        raw_bytes = raw_path.read_bytes()
        raw_candidate = _v4_global(_v4_scope, 'json').loads(raw_bytes.decode("utf-8-sig"))
        raw_sha256 = _v4_global(_v4_scope, 'hashlib').sha256(raw_bytes).hexdigest()
        valid_manifest = (
            raw_candidate == candidate
            and envelope_data.get("schema_version")
            == "v3.macos.research_panel_hk_capture_manifest.v1"
            and envelope_data.get("status") == "READY"
            and envelope_data.get("target_date") == target
            and envelope_data.get("capture_raw_sha256") == raw_sha256
            and envelope_data.get("capture_sha256") == candidate.get("capture_sha256")
            and envelope_data.get("codes") == candidate.get("codes")
        )
        if not valid_manifest:
            raise _v4_global(_v4_scope, 'SnapshotGateError')(
                "HK capture manifest is invalid or stale"
            )
        capture = candidate
    except (
        _v4_global(_v4_scope, 'OSError'),
        _v4_global(_v4_scope, 'UnicodeError'),
        _v4_global(_v4_scope, 'json').JSONDecodeError,
        _v4_global(_v4_scope, 'TypeError'),
        _v4_global(_v4_scope, 'ValueError'),
    ) as error:
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK capture manifest cannot be confirmed"
        ) from error
    if not _v4_global(_v4_scope, 'isinstance')(
        capture, _v4_global(_v4_scope, 'Mapping')
    ):
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK panel capture missing after collector"
        )
    membership_authority = membership_result.get("universe_authority")
    if (
        membership_result.get("capture_sha256") != capture.get("capture_sha256")
        or not _v4_global(_v4_scope, 'isinstance')(
            membership_authority, _v4_global(_v4_scope, 'Mapping')
        )
        or membership_authority.get("capture_sha256") != capture.get("capture_sha256")
        or membership_authority.get("capture_run_id") != capture.get("capture_run_id")
    ):
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK membership publication identity differs from final capture"
        )

    ensure_module._validated_capture(capture, trade_date=target, panel_sha256=None)
    source_payload = capture["source_payload"]
    expected_panel_codes = set(capture["codes"]) - set(source_payload["excluded_codes"])
    if (
        not _v4_global(_v4_scope, 'isinstance')(collected, _v4_global(_v4_scope, 'Mapping'))
        or collected.get("target_date") != target
        or collected.get("rows") != capture["rows"]
        or collected.get("source_sha256") != capture["source_sha256"]
    ):
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK snapshot coverage mismatch: collector rows differ from capture manifest"
        )
    packed = _v4_global(_v4_scope, 'pack_hk_day')(
        args.hk_tdx_root,
        capture["rows"],
        target_date=target,
        minimum_rows=600,
        expected_codes=expected_panel_codes,
    )

    packed_day_root = args.hk_tdx_root.expanduser().resolve() / "vipdoc" / "ds" / "lday"
    expected_day_names = {f"71#{code[3:]}.day" for code in expected_panel_codes}
    packed_files = packed.get("files") if _v4_global(
        _v4_scope, 'isinstance'
    )(packed, _v4_global(_v4_scope, 'Mapping')) else None
    if not _v4_global(_v4_scope, 'isinstance')(packed_files, _v4_global(_v4_scope, 'list')):
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK packed panel file ledger missing"
        )
    packed_paths = set()
    for item in packed_files:
        if (
            not _v4_global(_v4_scope, 'isinstance')(item, _v4_global(_v4_scope, 'Mapping'))
            or not item.get("path")
        ):
            raise _v4_global(_v4_scope, 'SnapshotGateError')(
                "HK packed panel file ledger invalid"
            )
        path = _v4_global(_v4_scope, 'Path')(str(item["path"])).expanduser().resolve()
        try:
            path.relative_to(packed_day_root)
        except ValueError as error:
            raise _v4_global(_v4_scope, 'SnapshotGateError')(
                "HK packed panel file escapes TDX root"
            ) from error
        if not path.is_file():
            raise _v4_global(_v4_scope, 'SnapshotGateError')(
                "HK packed panel file missing"
            )
        packed_paths.add(path)
    actual_day_names = {path.name for path in packed_paths}
    if len(packed_paths) != len(packed_files) or actual_day_names != expected_day_names:
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK packed panel code set mismatch: "
            f"actual={len(actual_day_names)},expected={len(expected_day_names)}"
        )

    stale_files = []
    orphan_files = []
    for path in sorted(packed_day_root.glob("*.day")):
        if not path.is_file() or path.name in expected_day_names:
            continue
        entry = {
            "path": str(path),
            "size_bytes": path.stat().st_size,
            "sha256": _v4_global(_v4_scope, 'hashlib').sha256(path.read_bytes()).hexdigest(),
        }
        bucket = (
            stale_files
            if path.name.startswith("71#")
            and path.name[3:-4].isdigit()
            and len(path.name[3:-4]) == 5
            else orphan_files
        )
        bucket.append(entry)

    authority = _v4_global(_v4_scope, 'run_hk_0_2_authority')(
        authority_paths["--hk-updater-script"],
        python_executable,
        authority_paths["--hk-asset-root"],
        args.hk_tdx_root,
        target,
    )
    panel_sha256 = authority.get("panel_sha256")
    if not ensure_module._is_sha256(panel_sha256):
        raise _v4_global(_v4_scope, 'SnapshotGateError')("HK panel authority SHA invalid")
    if authority.get("through_date_code_count") != len(expected_panel_codes):
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK panel and Futu capture universe coverage mismatch"
        )
    panel_sha256 = ensure_module._read_verified_hk_panel_authority(
        asset_root=asset_root,
        package_root=package_root,
        authority=authority,
        trade_date=target,
    )
    try:
        manifest = _v4_global(_v4_scope, 'json').loads(
            (asset_root / str(authority["manifest_relative"])).read_text(encoding="utf-8")
        )
        panel_path = (asset_root / str(manifest["panel_relative"])).resolve()
        panel_path.relative_to(asset_root)
        panel_rows = _v4_global(_v4_scope, '_panel_frame')(panel_path)
    except Exception as error:
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK panel authority parquet unreadable"
        ) from error
    raw_codes = [
        row.get("code_norm")
        for row in panel_rows
        if _v4_global(_v4_scope, '_compact_datetime')(row.get("trade_date_compact")) == target
    ]
    normalized_codes = [
        f"HK.{digits[-5:].zfill(5)}"
        if (digits := "".join(character for character in str(value or "") if character.isdigit()))
        else ""
        for value in raw_codes
    ]
    panel_codes = set(normalized_codes)
    if not raw_codes or any(not code for code in normalized_codes) or len(panel_codes) != len(raw_codes):
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK panel authority target code_norm invalid"
        )
    verified_panel_sha256 = ensure_module._read_verified_hk_panel_authority(
        asset_root=asset_root,
        package_root=package_root,
        authority=authority,
        trade_date=target,
    )
    if verified_panel_sha256.lower() != panel_sha256.lower():
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK panel SHA changed during code-set binding"
        )
    if panel_codes != expected_panel_codes:
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            f"HK panel code set mismatch: actual={len(panel_codes)},expected={len(expected_panel_codes)}"
        )
    panel_binding_sha256 = ensure_module._panel_capture_binding_sha256(
        capture, panel_sha256
    )
    security_master = ensure_module.ensure_hk_security_master(
        store_root=store_root,
        universe_root=store_root,
        shared_package_root=package_root,
        trade_date=target,
        futu_python=python_executable,
        capture=capture,
        panel_sha256=panel_sha256,
        panel_binding_sha256=panel_binding_sha256,
    )
    if security_master.get("panel_capture_binding_sha256") != panel_binding_sha256:
        raise _v4_global(_v4_scope, 'SnapshotGateError')(
            "HK panel capture binding SHA mismatch"
        )
    return {
        **collected,
        **packed,
        "authority": authority,
        "security_master": security_master,
        "panel_capture_binding_sha256": panel_binding_sha256,
        "source_sha256": collected["source_sha256"],
        "persistent_stale_files": stale_files,
        "persistent_orphan_files": orphan_files,
        "persistent_out_of_scope_count": len(stale_files) + len(orphan_files),
    }
